      case LV_EVENT_RELEASED:
        return "released";
      case LV_EVENT_LONG_PRESSED:
        return "long_pressed";
      case LV_EVENT_SCROLL_BEGIN:
        return "scroll_begin";
      case LV_EVENT_SCROLL:
        return "scroll";
      case LV_EVENT_SCROLL_END:
        return "scroll_end";
      case LV_EVENT_VALUE_CHANGED:
        return "value_changed";
      default:
        return "event";
    }
}

